        door,
        rule: 'remote-delete',
        targets,
        why: `${what} deletes on the remote, past any trash`,
    });
    if (
        c.name === 'gh' &&
        (ops[0] === 'repo' || ops[0] === 'release') &&
        /^delete/.test(ops[1] ?? '')
