const RG_VALUE = new Set([
    '-e',
    '--regexp',
    '-f',
    '--file',
    '-g',
    '--glob',
    '--iglob',
    '-t',
    '--type',
    '-T',
    '--type-not',
    '-A',
    '-B',
    '-C',
    '--after-context',
    '--before-context',
    '--context',
    '-m',
    '--max-count',
    '--max-depth',
    '-d',
    '-r',
    '--replace',
    '-M',
    '--max-columns',
    '-j',
    '--threads',
    '--sort',
    '--sortr',
    '--encoding',
    '-E',
]);
