const QUICK = new Set([
    'cd',
    'echo',
    'printf',
    'cat',
    'ls',
    'head',
    'tail',
    'rg',
    'grep',
    'jq',
    'sed',
    'awk',
    'tee',
    'true',
    'test',
    'wc',
    'sort',
    'uniq',
    'cut',
    'tr',
    'export',
    'set',
    'sleep',
    'date',
    'trash',
    'mkdir',
    'cp',
    'mv',
