export function foregroundClaude(
    command: string,
    cwd: string,
): Refusal | undefined {
    const parsed = parse(command);
    if (parsed.comments.some((c) => /^\s*fg-ok:\s*\S/.test(c)))
        return undefined;
    const isClaudeP = commands(parsed, cwd).some(
        (c) =>
            c.name === 'claude' &&
            c.args.some((w) => w.text === '-p' || w.text === '--print'),
    );
