export function rawPluginUpdate(
    command: string,
    cwd: string,
): Refusal | undefined {
    for (const c of commands(parse(command), cwd)) {
        if (c.name !== 'claude') continue;
        const [a, b, d] = c.args.map((w) => w.text);
        if (a !== 'plugin') continue;
        const isUpdate =
            b === 'update' || (b === 'marketplace' && d === 'update');
