        if (!name) {
            add('$');
            i++;
            return;
        }
        // zsh reads `$name:x` as a modifier when x is a letter; bash reads a non-ascii character as part of the name
        const after = command[i + 1 + name.length] ?? '';
        const modifier = command[i + 2 + name.length] ?? '';
