    };
    const skipHeredocs = () => {
        while (heredocs.length) {
            const delimiter = heredocs.shift();
            while (i < command.length) {
                const end = command.indexOf('\n', i);
                const line = command.slice(i, end < 0 ? undefined : end);
                i = end < 0 ? command.length : end + 1;
                if (line.trim() === delimiter) break;
            }
        }
    };
    const heredoc = () => {
        endWord();
        i += 2;
        if (command[i] === '-') i++;
        while (command[i] === ' ' || command[i] === '\t') i++;
        const quote = command[i];
        let delimiter = '';
        if (quote === "'" || quote === '"') {
            const end = command.indexOf(quote, i + 1);
            delimiter = command.slice(i + 1, end < 0 ? undefined : end);
            i = end < 0 ? command.length : end + 1;
        } else {
            while (
                i < command.length &&
                !/[\s;&|<>()]/.test(command[i] ?? '')
            ) {
                delimiter += command[i] === '\\' ? '' : command[i];
                i++;
            }
        }
        if (delimiter) heredocs.push(delimiter);
    };

    while (i < command.length) {
        const c = command[i] ?? '';
        const next = command[i + 1] ?? '';
        if (isQuoted) {
            if (c === '"') {
                isQuoted = false;
                i++;
            } else if (c === '\\') {
                add(next);
                i += 2;
            } else if (c === '$') dollar();
            else if (c === '`') {
                i++;
                quoted('tick');
            } else {
                add(c);
                i++;
            }
        } else if (c === '\n') {
            i++;
            endSegment(';');
            skipHeredocs();
        } else if (c === ' ' || c === '\t') {
            endWord();
            i++;
        } else if (c === '#' && !isWord) {
            const end = command.indexOf('\n', i);
            comments.push(command.slice(i + 1, end < 0 ? undefined : end));
            i = end < 0 ? command.length : end;
        } else if (c === '\\') {
            add(next === '\n' ? '' : next);
            hasQuote = true;
            i += 2;
        } else if (c === "'") {
            const end = command.indexOf("'", i + 1);
            add(command.slice(i + 1, end < 0 ? undefined : end));
            hasQuote = true;
            i = end < 0 ? command.length : end + 1;
        } else if (c === '"') {
            isWord = true;
            isBare = false;
            hasQuote = true;
            isQuoted = true;
            i++;
        } else if (c === '$') {
            dollar();
        } else if (c === '`') {
            i++;
            if (stack.at(-1)?.kind === 'tick') {
                close();
                resume();
            } else open('tick');
        } else if (c === '(') {
            i++;
            open('group');
        } else if (c === ')') {
            i++;
            close();
            resume();
        } else if (c === ';') {
            i += next === ';' ? 2 : 1;
            endSegment(';');
        } else if (c === '&') {
            if (next === '&') {
                i += 2;
                endSegment('&&');
            } else if (next === '>' || /[<>]$/.test(text)) {
                add('&');
                i++;
            } else {
                i++;
                endSegment('&');
            }
        } else if (c === '|') {
            if (next === '|') {
                i += 2;
                endSegment('||');
            } else {
                i += next === '&' ? 2 : 1;
                endSegment('|');
            }
        } else if (c === '<' && next === '<' && command[i + 2] !== '<') {
            heredoc();
        } else {
            add(c, true);
            i++;
        }
    }
    while (stack.length)
        if (stack.at(-1)?.kind === 'dq') stack.pop();
        else close();
    endSegment(';');
    return { comments, segments, unbraced };
}

files.hooks/rules/floor.ts:
import {
    ASK,
    type Command,
    type Context,
    NEVER,
    type Refusal,
    STASH,
    TRASH,
    VAULT,
    gitDir,
    gitParts,
    hasFlag,
    operands,
    or,
    peel,
} from './command.ts';
import { isOwnRepo } from './hazard.ts';
import { rewrite } from './rewrite.ts';

// what reads process ids by name
const FINDERS = new Set(['pgrep', 'ps', 'pidof', 'lsof', 'grep', 'rg', 'awk']);
export function floor(c: Command, ctx: Context): Refusal | undefined {
    const ops = operands(c.args);
    if (c.name === 'rm' || c.name === 'unlink')
        return {
            door: TRASH,
            rule: 'rm',
            targets: or(ops, 'rm'),
            why: 'rm deletes for good',
        };
    if (c.name === 'find') {
        const exec = c.args.findIndex((w) =>
            /^-(exec|execdir|ok)$/.test(w.text),
        );
        const execRm = exec >= 0 && peel(c.args.slice(exec + 1)).name === 'rm';
        if (execRm || hasFlag(c.args, ['-delete'])) {
            const roots = c.args.findIndex((w) => /^[-(!]/.test(w.text));
            const paths = c.args
                .slice(0, roots < 0 ? undefined : roots)
                .map((w) => w.text);
            return {
                door: TRASH,
                rule: 'rm',
                targets: or(paths, '.'),
                why: 'find deletes for good',
            };
        }
    }
    const pgrep = c.feeders.find((f) => f.name === 'pgrep');
    if (
        c.name === 'pkill' ||
        c.name === 'killall' ||
        (c.name === 'kill' && c.feeders.some((f) => FINDERS.has(f.name)))
    )
        return {
            door: 'claude stop <id>, or kill the pid you captured at spawn',
            rule: 'kill',
            targets: or(
                c.name === 'kill' ? operands(pgrep?.args ?? []) : ops,
                c.name,
            ),
            why: 'a kill by pattern hits your own process too',
        };
    if (
        c.name === 'mv' &&
        (c.dir.includes(VAULT) || ops.some((o) => o.includes(VAULT)))
    )
        return {
            door: 'obsidian rename / obsidian move — they rewrite the wikilinks',
            rule: 'vault-mv',
            targets: ops,
            why: 'a plain mv in the vault breaks every wikilink to the note',
        };
    if (
        c.assigns.some((a) => a.startsWith('HOME=')) ||
        (c.name === 'export' && ops.some((o) => o.startsWith('HOME=')))
    )
        return {
            door: 'run it without the HOME override',
            rule: 'home',
            targets: ['HOME'],
            why: 'a HOME override points every tool at the wrong config',
        };
    if (
        c.name === 'npm' &&
        hasFlag(c.args, ['--global', '--location=global'], 'g')
    )
        return {
            door: 'brew first, else pnpm add -g',
            rule: 'npm-global',
            targets: ['npm'],
            why: 'npm -g is not used here',
        };
    const isPip = /^pip\d*(\.\d+)?$/.test(c.name) && ops[0] === 'install';
    const pipAt = c.args.findIndex(
        (w, i) => w.text === '-m' && c.args[i + 1]?.text === 'pip',
    );
    const isPyPip =
        /^python\d*(\.\d+)?$/.test(c.name) &&
        pipAt >= 0 &&
        operands(c.args.slice(pipAt + 2))[0] === 'install';
    if (isPip || isPyPip)
        return {
            door: 'uv pip install',
            rule: 'pip',
            targets: ['pip'],
            why: 'pip is not used here; uv is',
        };
    const bypass = c.args.find(
        (w) => w.text === '--no-verify' || w.text === '--no-gpg-sign',
    );
    if (bypass && (c.name === 'git' || c.name === 'x'))
        return {
            door: NEVER,
            rule: 'bypass',
            targets: [bypass.text],
            why: `${bypass.text} skips a gate`,
        };
    if (c.name !== 'git') return undefined;

    const { configs, sub, subArgs } = gitParts(c.args);
    const subOps = operands(subArgs);
    const config = configs.find(
        (k) =>
            /^commit\.gpgsign=false$/i.test(k) ||
            /^user\.(name|email)=/i.test(k),
    );
    if (config) {
        const key = config.split('=')[0] ?? config;
        return {
            door: NEVER,
            rule: 'bypass',
            targets: [key],
            why: `-c ${key} overrides signing or identity`,
        };
    }
    const discard = (targets: string[], what: string): Refusal => ({
        door: STASH,
        rule: 'git-discard',
        targets,
        why: `${what} throws away uncommitted work`,
    });
    if (sub === 'commit' && hasFlag(subArgs, [], 'n'))
        return {
            door: NEVER,
            rule: 'bypass',
            targets: ['-n'],
            why: 'git commit -n skips the commit hooks',
        };
    if (
        sub === 'config' &&
        /^user\.(name|email)$/i.test(subOps[0] ?? '') &&
        subOps.length > 1
    )
        return {
            door: NEVER,
            rule: 'bypass',
            targets: [subOps[0] ?? ''],
            why: 'git config changes the commit identity',
        };
    if (sub === 'reset' && hasFlag(subArgs, ['--hard']))
        return discard(or(subOps, 'HEAD'), 'git reset --hard');
    if (
        sub === 'checkout' &&
        (subArgs.some((w) => w.text === '--') ||
            subOps.includes('.') ||
            hasFlag(subArgs, ['--force'], 'f'))
    )
        return discard(or(subOps, '.'), 'git checkout over files');
    if (
        sub === 'restore' &&
        !(
            hasFlag(subArgs, ['--staged'], 'S') &&
            !hasFlag(subArgs, ['--worktree'], 'W')
        )
    )
        return discard(or(subOps, '.'), 'git restore');
    if (sub === 'clean' && hasFlag(subArgs, ['--force'], 'f'))
        return discard(or(subOps, '.'), 'git clean');
    if (sub === 'stash' && (subOps[0] === 'drop' || subOps[0] === 'clear'))
        return {
            door: ASK,
            rule: 'git-discard',
            targets: or(
                subOps.slice(1),
                subOps[0] === 'drop' ? 'stash@{0}' : 'clear',
            ),
            why: `git stash ${subOps[0]} throws away set-aside work`,
        };
    const rewrite = (targets: string[], what: string): Refusal => ({
        door: ASK,
        rule: 'git-rewrite',
        targets,
        why: `${what} cannot be undone`,
    });
    if (
        sub === 'push' &&
        (hasFlag(
            subArgs,
            ['--force', '--force-with-lease', '--delete'],
            'fd',
        ) ||
            subOps.slice(1).some((o) => /^[+:]/.test(o)))
    )
        return rewrite(or(subOps, 'push'), 'a force-push');
    if (
        sub === 'branch' &&
        (hasFlag(subArgs, [], 'D') ||
            (hasFlag(subArgs, ['--delete'], 'd') &&
                hasFlag(subArgs, ['--force'], 'f')))
    )
        return rewrite(subOps, 'git branch -D');
    if (sub === 'filter-repo' || sub === 'filter-branch')
        return rewrite([sub], `git ${sub}`);
    if (sub === 'gc' && hasFlag(subArgs, ['--prune=now']))
        return rewrite(['--prune=now'], 'git gc --prune=now');
    if (sub === 'worktree' && subOps[0] === 'prune')
        return rewrite(['prune'], 'git worktree prune');
    if (sub === 'worktree' && subOps[0] === 'remove')
        return rewrite(or(subOps.slice(1), 'remove'), 'git worktree remove');
    const toMain = subOps
        .slice(1)
        .find((o) => /^[^+:][^:]*:(refs\/heads\/)?main$/.test(o));
    if (sub === 'push' && toMain && isOwnRepo(gitDir(c, ctx), ctx))
        return {
            door: "x lane push — it pushes HEAD's sha and reads the remote back",
            rule: 'push-lane',
            targets: [toMain],
            why: 'a hand-typed sha or ref pushed to main skips the read-back',
        };
    return undefined;
}

files.hooks/rules/lint.ts:
import type { Parsed, Word } from '../shell.ts';
import {
    type Command,
    LANE,
    type Refusal,
    SD_VALUE,
    gitParts,
    hasFlag,
    isFlag,
    operands,
} from './command.ts';

const GREPS = new Set([
    'grep',
    'egrep',
    'fgrep',
    'rg',
    'ugrep',
    'head',
    'tail',
]);
// a script named for a gate, a family member included: `typecheck`, `test:unit`, `mods:test`, `x-go:gate`
const GATE = /(^|:)(typecheck|test|check|tsc|vitest|gate)(:|$)/;
// a gate tool run to list or print, which checks nothing
const LISTING = [
    '--help',
    '-h',
    '--version',
    '-v',
    '--listFiles',
    '--listFilesOnly',
    '--showConfig',
];
const SD_FLAGS = new Set([
    '-p',
    '--preview',
    '-F',
    '--fixed-strings',
    '-s',
    '--string-mode',
    '-n',
    '--max-replacements',
    '-f',
    '--flags',
    '-h',
    '--help',
    '-V',
    '--version',
]);
export function lint(
    c: Command,
    next: Command | undefined,
): Refusal | undefined {
    const ops = operands(c.args);
    const pipedTo =
        c.sep === '|' && next && GREPS.has(next.name) ? next.name : undefined;
    // a knowledge read is logged as read: one whose text never reaches the session fakes the proof (FRM-371)
    if (
        c.name === 'x' &&
        ops[0] === 'knowledge' &&
        ops[1] === 'read' &&
        c.stdouts.length
    )
        return {
            door: `read it plainly: x knowledge read ${ops[2] ?? '<name>'}, its text in the session (| head is fine)`,
            rule: 'knowledge-read-hidden',
            targets: [ops[2] ?? 'knowledge'],
            why: `its stdout goes to ${c.stdouts.join(', ')}, so the read is logged and nothing reaches the session`,
        };
    if (c.name === 'sd') {
        const hasEnd = c.args.some((w) => w.text === '--');
        const positional: Word[] = [];
        for (let i = 0; i < c.args.length; i++) {
            const w = c.args[i] as Word;
            if (w.text === '--') {
                positional.push(...c.args.slice(i + 1));
                break;
            }
            if (!isFlag(w.text)) positional.push(w);
            else if (!hasEnd && !SD_FLAGS.has(w.text))
                return {
                    door: `sd -- '${w.text}' …`,
                    rule: 'sd-dash',
                    targets: ['sd'],
                    why: `sd reads ${w.text} as a flag and edits nothing`,
                };
            else if (SD_VALUE.has(w.text)) i++;
        }
        // a `$` in the replacement is lost either way: the shell expands it in double quotes, sd reads `$NAME` as a capture ref in single
        const replacement = positional[1];
        if (replacement?.isExpanding || replacement?.text.includes('$'))
            return {
                door: 'python or the Edit tool for a replacement holding $',
                rule: 'sd-dollar',
                targets: ['sd'],
                why: replacement.isExpanding
                    ? 'the shell expands $ inside double quotes and the line ships hollow'
                    : 'sd reads $NAME in the replacement as a capture group and writes it empty',
            };
        if (
            !hasFlag(c.args, ['--preview'], 'p') &&
            ops.some((o) => o.includes('.github/workflows/'))
        )
            return {
                door: 'the Edit tool',
                rule: 'workflow-edit',
                targets: ['sd'],
                why: 'sd drops ${{ … }} from a workflow line',
            };
    }
    // the obsidian cli runs a verb on the active note: `delete --help` deleted memory-sweep.md (2026-10-07)
    if (c.name === 'obsidian' && ops.length > 0) {
        if (hasFlag(c.args, ['--help'], 'h'))
            return {
                door: 'obsidian --help, bare: it lists every verb with its options',
                rule: 'obsidian-help',
                targets: ['obsidian'],
                why: `obsidian ${ops[0]} --help runs ${ops[0]} on the active note instead of printing help`,
            };
        if (
            ops[0] === 'delete' &&
            !ops.some((o) => o.startsWith('path=') || o.startsWith('file='))
        )
            return {
                door: 'obsidian delete path=<vault path>',
                rule: 'obsidian-delete-target',
                targets: ['obsidian'],
                why: 'a delete with no file named deletes the active note',
            };
    }
    if (
        (c.name === 'sed' || c.name === 'gsed') &&
        hasFlag(c.args, ['--in-place'], 'i') &&
        ops.some((o) => o.includes('.github/workflows/'))
    )
        return {
            door: 'the Edit tool',
            rule: 'workflow-edit',
            targets: ['sed'],
            why: 'sed drops ${{ … }} from a workflow line',
        };
    if (pipedTo && c.name === 'git' && gitParts(c.args).sub === 'push')
        return {
            door: 'git ls-remote <remote> <branch>',
            rule: 'push-grep',
            targets: [pipedTo],
            why: 'a push is read by git ls-remote, never by its output',
        };
    const isListing =
        hasFlag(c.args, LISTING) || ops.includes('list') || ops.includes('ls');
    const isGate =
        !isListing &&
        (['tsc', 'vitest'].includes(c.name) ||
            (['pnpm', 'npm', 'yarn', 'bun'].includes(c.name) &&
                ops.some((o) => GATE.test(o))));
    if (pipedTo && isGate)
        return {
            door: 'run the gate unpiped and read its exit code',
            rule: 'gate-pipe',
            targets: [pipedTo],
            why: `| ${pipedTo} turns a red gate quiet`,
        };
    // zsh never splits an unquoted parameter: `set -- $PIDS` sets one arg, and a watch on `$1` dies silent
    const dashes = c.args.findIndex((w) => w.text === '--');
    const unsplit =
        c.name === 'set' && dashes >= 0
            ? c.args
                  .slice(dashes + 1)
                  .find(
                      (w) =>
                          !w.hasQuote &&
                          /^\$\{?[A-Za-z_]/.test(w.text) &&
                          !w.text.startsWith('${='),
                  )
            : undefined;
    if (unsplit) {
        const name = unsplit.text.replace(/^\$\{?|\}$/g, '');
        return {
            door: `\${=${name}} — zsh's split — or write the items out`,
            rule: 'set-unsplit',
            targets: [unsplit.text],
            why: `zsh does not split ${unsplit.text}, so set -- gets one argument`,
        };
    }
    if (c.name === 'git') {
        const { sub, subArgs } = gitParts(c.args);
        if (sub === 'commit' && !subArgs.some((w) => w.text === '--'))
            return {
                door: LANE,
                rule: 'git-sweep',
                targets: ['commit'],
                why: 'a commit with no -- paths sweeps whatever is staged',
            };
        const sweep = subArgs.find(
            (w) => w.text === '-A' || w.text === '--all' || w.text === '.',
        );
        if (sub === 'add' && sweep)
            return {
                door: LANE,
                rule: 'git-sweep',
                targets: [sweep.text],
                why: `git add ${sweep.text} stages files that are not yours`,
            };
    }
    return undefined;
}
export function unbraced(parsed: Parsed): Refusal | undefined {
    const [first] = parsed.unbraced;
    if (!first) return undefined;
    const name = first.slice(1, -1);
    return {
        door: `\${${name}}`,
        rule: 'unbraced',
        targets: [`$${name}`],
        why: `${first} — zsh reads a modifier, bash a longer name`,
    };
}
export function background(list: Command[]): Refusal | undefined {
    const last = list.findLastIndex((c) => c.sep === '&');
    if (
        last < 0 ||
        list
            .slice(last + 1)
            .some((c) => c.name === 'wait' || c.name === 'sleep')
    )
        return undefined;
    return {
        door: 'add wait (or a sleep) after it, or use run_in_background',
        rule: 'background',
        targets: ['&'],
        why: 'the tool wrapper exits and kills a trailing & child',
    };
}

files.hooks/rules/lockfile.ts:
import {
    type Command,
    type Context,
    type Refusal,
    resolve,
} from './command.ts';

// `CI=1` makes pnpm freeze the lockfile: a dep add or removal, or an install over a changed manifest, leaves the
// lockfile behind and the commit ships half (FRM-393, was a fleet-hazards line)
const ADDS = new Set(['add', 'remove', 'rm', 'uninstall', 'un']);
const INSTALLS = new Set(['install', 'i']);
const isFrozenPnpm = (c: Command) =>
    c.name === 'pnpm' &&
    c.assigns.some((a) => /^CI=(1|true)$/.test(a)) &&
    !c.args.some((w) => w.text === '--no-frozen-lockfile');

// the dirs whose `CI=1 pnpm install` needs a manifest check before it is judged
export function frozenInstallDirs(cs: Command[], ctx: Context) {
    return cs
        .filter((c) => isFrozenPnpm(c) && INSTALLS.has(c.args[0]?.text ?? ''))
        .map((c) => resolve(c.dir, '/', ctx));
}

export function lockfile(c: Command, ctx: Context): Refusal | undefined {
    if (!isFrozenPnpm(c)) return undefined;
    const verb = c.args[0]?.text ?? '';
    const isAdd = ADDS.has(verb);
    const isChangedInstall =
        INSTALLS.has(verb) && !!ctx.manifestDirs?.has(resolve(c.dir, '/', ctx));
    if (!isAdd && !isChangedInstall) return undefined;
    return {
        door: `add --no-frozen-lockfile: CI=1 pnpm ${verb} --no-frozen-lockfile …`,
        rule: 'frozen-lockfile',
        targets: [`pnpm ${verb}`],
        why: isAdd
            ? 'CI=1 freezes the lockfile, so the dep change never reaches it and the commit ships half'
            : 'a package.json or pnpm-workspace.yaml changed, and CI=1 freezes the lockfile against it',
    };
}

